// Packages: Azure.Identity, Azure.Storage.Blobs, Azure.Security.KeyVault.Secrets
// Install: dotnet add package Azure.Identity
//         dotnet add package Azure.Storage.Blobs
//         dotnet add package Azure.Security.KeyVault.Secrets

using Azure.Identity;
using Azure.Storage.Blobs;
using Azure.Security.KeyVault.Secrets;

public class AzureAuthDemo
{
    private readonly DefaultAzureCredential _credential;

    public AzureAuthDemo() => _credential = new DefaultAzureCredential();

    public async Task RunAsync(CancellationToken ct = default)
    {
        try
        {
            // Blob Storage with token credential
            var blobUri = new Uri("https://demostorage.blob.core.windows.net");
            var blobService = new BlobServiceClient(blobUri, _credential);
            var container = blobService.GetBlobContainerClient("uploads");
            await container.CreateIfNotExistsAsync(cancellationToken: ct);

            // Key Vault with the same credential type
            var keyVaultUri = new Uri("https://demo-vault.vault.azure.net/");
            var secretClient = new SecretClient(keyVaultUri, _credential);
            KeyVaultSecret secret = await secretClient.GetSecretAsync(
                "ConnectionStrings--Default", cancellationToken: ct);

            Console.WriteLine($"Container exists: {await container.ExistsAsync(ct)}");
            Console.WriteLine($"Secret loaded, length: {secret.Value.Length}");
        }
        catch (AuthenticationFailedException ex)
        {
            Console.WriteLine($"Auth failed: {ex.Message}");
            throw;
        }
    }
}

// Usage
var demo = new AzureAuthDemo();
await demo.RunAsync();

// Expected output (when authenticated):
// Container exists: True
// Secret loaded, length: 47

// Packages: Azure.Storage.Blobs, Azure.Security.KeyVault.Secrets, Azure.Identity
// Install: dotnet add package Azure.Storage.Blobs
//         dotnet add package Azure.Security.KeyVault.Secrets
//         dotnet add package Azure.Identity

using Azure.Storage.Blobs;
using Azure.Security.KeyVault.Secrets;
using Azure.Identity;

var builder = WebApplication.CreateBuilder(args);

// Register Azure clients via AddAzureClients
builder.Services.AddAzureClients(clientBuilder =>
{
    clientBuilder.AddBlobServiceClient(
        builder.Configuration["Azure:Storage:BlobUri"]!);

    clientBuilder.AddSecretClient(
        new Uri(builder.Configuration["Azure:KeyVault:Uri"]!));
});

// Register typed business-logic wrapper for DI
builder.Services.AddScoped<BlobStorageService>();

var app = builder.Build();
app.MapGet("/", () => "Azure SDK ready");
app.Run();

public class BlobStorageService
{
    private readonly BlobContainerClient _container;

    public BlobStorageService(BlobServiceClient blobClient, IConfiguration config)
    {
        var containerName = config["Azure:Storage:Container"] ?? "uploads";
        _container = blobClient.GetBlobContainerClient(containerName);
    }

    public async Task EnsureContainerExistsAsync(CancellationToken ct = default)
        => await _container.CreateIfNotExistsAsync(cancellationToken: ct);
}
